import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { PortalLayout, PortalHeader } from "@/components/tekillah/vendor/PortalLayout";
import { StatusBanner } from "@/components/tekillah/vendor/StatusBanner";
import { usePartnerVendor } from "@/hooks/usePartnerVendor";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Download, Plus, Receipt, TrendingUp, Calendar } from "lucide-react";
import { toast } from "sonner";
import jsPDF from "jspdf";
import autoTable from "jspdf-autotable";

const fmt = (n: number) => Math.round(n).toLocaleString("en-US");

type Invoice = {
  id: string; invoice_number: string; customer_name: string | null; customer_phone: string | null;
  issue_date: string; subtotal: number; vat_amount: number; total: number; status: string; source: string; notes: string | null;
};

const PartnerInvoicesPage = () => {
  const { vendor } = usePartnerVendor();
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [open, setOpen] = useState(false);
  const [form, setForm] = useState({ customer_name: "", customer_phone: "", amount: "", notes: "" });

  const load = async () => {
    if (!vendor) return;
    const { data } = await supabase.from("vendor_invoices" as never).select("*").eq("vendor_id", vendor.id).order("issue_date", { ascending: false });
    setInvoices(((data as unknown) as Invoice[]) || []);
  };
  useEffect(() => { load(); /* eslint-disable-next-line */ }, [vendor]);

  const stats = invoices.reduce((acc, inv) => ({
    count: acc.count + 1, total: acc.total + Number(inv.total), vat: acc.vat + Number(inv.vat_amount),
  }), { count: 0, total: 0, vat: 0 });

  const create = async () => {
    if (!vendor) return;
    const amt = parseFloat(form.amount);
    if (!amt || amt <= 0) { toast.error("أدخل مبلغاً صحيحاً"); return; }
    const subtotal = +(amt / 1.15).toFixed(2);
    const vat = +(amt - subtotal).toFixed(2);
    const { data: numData } = await supabase.rpc("generate_vendor_invoice_number" as never);
    const { error } = await supabase.from("vendor_invoices" as never).insert({
      vendor_id: vendor.id, invoice_number: numData as unknown as string,
      customer_name: form.customer_name || null, customer_phone: form.customer_phone || null,
      subtotal, vat_amount: vat, total: amt, notes: form.notes || null, source: "manual",
    } as never);
    if (error) { toast.error(error.message); return; }
    toast.success("تم إصدار الفاتورة");
    setForm({ customer_name: "", customer_phone: "", amount: "", notes: "" });
    setOpen(false); load();
  };

  const downloadPDF = (inv: Invoice) => {
    const doc = new jsPDF();
    doc.setFont("helvetica", "bold"); doc.setFontSize(20);
    doc.text("TAX INVOICE", 105, 20, { align: "center" });
    doc.setFontSize(11); doc.setFont("helvetica", "normal");
    doc.text(`Invoice #: ${inv.invoice_number}`, 14, 35);
    doc.text(`Date: ${inv.issue_date}`, 14, 42);
    doc.text(`Vendor: ${vendor?.business_name ?? ""}`, 14, 49);
    doc.text(`Customer: ${inv.customer_name ?? "-"}`, 14, 56);
    autoTable(doc, {
      startY: 70,
      head: [["Description", "Subtotal (SAR)", "VAT 15%", "Total (SAR)"]],
      body: [["Venue booking service", fmt(inv.subtotal), fmt(inv.vat_amount), fmt(inv.total)]],
      theme: "grid", headStyles: { fillColor: [82, 92, 50] },
    });
    const finalY = (doc as unknown as { lastAutoTable: { finalY: number } }).lastAutoTable.finalY + 10;
    doc.setFont("helvetica", "bold");
    doc.text(`TOTAL: ${fmt(inv.total)} SAR`, 196, finalY, { align: "right" });
    doc.setFontSize(9); doc.setFont("helvetica", "normal");
    doc.text("Generated by TKLH تِكله — tiklh.com", 105, 285, { align: "center" });
    doc.save(`${inv.invoice_number}.pdf`);
  };

  return (
    <PortalLayout>
      <PortalHeader
        title="الفواتير الضريبية"
        subtitle="إصدار وأرشفة الفواتير الضريبية ZATCA"
        badge="ZATCA متوافق"
        action={
          <Dialog open={open} onOpenChange={setOpen}>
            <DialogTrigger asChild><Button><Plus className="ml-2 h-4 w-4" /> فاتورة جديدة</Button></DialogTrigger>
            <DialogContent dir="rtl">
              <DialogHeader><DialogTitle>إصدار فاتورة يدوية</DialogTitle></DialogHeader>
              <div className="space-y-3">
                <div><Label>اسم العميل</Label><Input value={form.customer_name} onChange={(e) => setForm({ ...form, customer_name: e.target.value })} /></div>
                <div><Label>الجوال</Label><Input value={form.customer_phone} onChange={(e) => setForm({ ...form, customer_phone: e.target.value })} /></div>
                <div>
                  <Label>المبلغ شامل الضريبة ()</Label>
                  <Input type="number" value={form.amount} onChange={(e) => setForm({ ...form, amount: e.target.value })} />
                  {form.amount && (
                    <p className="mt-1 text-xs text-muted-foreground">
                      صافي: {fmt(parseFloat(form.amount) / 1.15)}  + ضريبة 15%: {fmt(parseFloat(form.amount) - parseFloat(form.amount) / 1.15)} 
                    </p>
                  )}
                </div>
                <div><Label>ملاحظات</Label><Input value={form.notes} onChange={(e) => setForm({ ...form, notes: e.target.value })} /></div>
                <Button onClick={create} className="w-full">إصدار</Button>
              </div>
            </DialogContent>
          </Dialog>
        }
      />
      <StatusBanner vendor={vendor} />
      <div className="mb-6 grid grid-cols-1 gap-4 md:grid-cols-3">
        <Card className="p-5"><Receipt className="h-5 w-5 text-primary" /><div className="mt-3 text-2xl font-black">{fmt(stats.count)}</div><div className="mt-1 text-xs font-bold text-muted-foreground">إجمالي الفواتير</div></Card>
        <Card className="border-primary bg-primary p-5 text-primary-foreground"><TrendingUp className="h-5 w-5 text-secondary" /><div className="mt-3 text-2xl font-black">{fmt(stats.total)} </div><div className="mt-1 text-xs font-bold text-primary-foreground/70">إجمالي القيمة</div></Card>
        <Card className="p-5"><Calendar className="h-5 w-5 text-primary" /><div className="mt-3 text-2xl font-black">{fmt(stats.vat)} </div><div className="mt-1 text-xs font-bold text-muted-foreground">ضريبة محصّلة</div></Card>
      </div>
      <Card className="overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead className="border-b border-border bg-muted/60"><tr className="text-right text-xs font-black text-foreground/70"><th className="p-4">رقم الفاتورة</th><th className="p-4">التاريخ</th><th className="p-4">العميل</th><th className="p-4">المبلغ</th><th className="p-4">المصدر</th><th className="p-4"></th></tr></thead>
            <tbody>
              {invoices.length === 0 && <tr><td colSpan={6} className="p-10 text-center text-muted-foreground">لا توجد فواتير بعد. أصدر أول فاتورة 👆</td></tr>}
              {invoices.map((inv) => (
                <tr key={inv.id} className="border-b border-border last:border-0 hover:bg-muted/40">
                  <td className="p-4 font-mono font-bold text-primary">{inv.invoice_number}</td>
                  <td className="p-4 text-muted-foreground">{new Date(inv.issue_date).toLocaleDateString("ar-SA")}</td>
                  <td className="p-4">{inv.customer_name || "-"}</td>
                  <td className="p-4 font-black">{fmt(inv.total)} </td>
                  <td className="p-4"><span className="rounded-full bg-secondary px-2 py-1 text-[10px] font-black text-primary-deep">{inv.source === "auto" ? "تلقائي" : "يدوي"}</span></td>
                  <td className="p-4"><Button size="sm" variant="ghost" onClick={() => downloadPDF(inv)} className="text-primary"><Download className="ml-1 h-4 w-4" /> PDF</Button></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </Card>
    </PortalLayout>
  );
};

export default PartnerInvoicesPage;
